import json, random, sys
sys.path.insert(0, '/workspace/tmp/dev')
from harness import run_ok, wmanifest
from test_plan import independent_plan

def rand_valid(rng):
    m = {'version': 1, 'seed': rng.randrange(0, 2**64), 'low_count': rng.randint(1, 32),
         'attempts': rng.randint(1, 3), 'spacing_ms': rng.randint(1, 1000),
         'timeout_ms': rng.randint(1, 1000000), 'windows': []}
    for wi in range(rng.randint(0, 8)):
        wid = 'w%d' % wi
        if rng.random() < 0.3:
            wid = 'W-%d_%d' % (wi, rng.randrange(0, 9))
        scopes = []
        used = set()
        for si in range(rng.randint(0, 8)):
            for _ in range(20):
                if rng.random() < 0.5:
                    pre = '2001:db8:%x:%02x00::/56' % (rng.randrange(0, 65536), rng.randrange(0, 256))
                    subs = rng.sample(range(256), k=rng.randint(1, 8))
                    nets = {(int.from_bytes(bytes.fromhex(pre.split(':')[1] + pre.split(':')[2].rjust(4,'0')), 'big') << 32) + (int(pre.split(':')[3][:2], 16) << 16) if False else 0}
                    # compute /64 bases properly
                    import ipaddress
                    b0 = int(ipaddress.IPv6Network(pre).network_address)
                    cand = [b0 + (s << 64) for s in subs]
                else:
                    pre = '2001:db8:%x:%02x01::/64' % (rng.randrange(0, 65536), rng.randrange(0, 256))
                    subs = [0]
                    import ipaddress
                    cand = [int(ipaddress.IPv6Network(pre).network_address)]
                if not any(c in used for c in cand):
                    used.update(cand)
                    scopes.append({'id': 's%d' % si, 'prefix': pre, 'subnets': subs})
                    break
        m['windows'].append({'id': wid, 'start_ms': rng.choice([0, 1, 10**12, rng.randrange(0, 10**12)]), 'scopes': scopes})
    return m

def main():
    rng = random.Random(int(sys.argv[1]))
    trials = int(sys.argv[2])
    fails = 0
    for t in range(trials):
        m = rand_valid(rng)
        # shuffle all arrays
        rng.shuffle(m['windows'])
        for w in m['windows']:
            rng.shuffle(w['scopes'])
            for s in w['scopes']:
                rng.shuffle(s['subnets'])
        got = run_ok(['plan', wmanifest(m)])
        exp = independent_plan(m)
        if got != exp:
            fails += 1
            print('PLAN MISMATCH', json.dumps(m)[:600])
            gp = {p['id']: p for p in got['probes']}
            ep = {p['id']: p for p in exp['probes']}
            if set(gp) != set(ep):
                print(' id sets differ', list(set(gp) ^ set(ep))[:5], len(gp), len(ep))
            for k in sorted(set(gp) & set(ep))[:2000]:
                if gp[k] != ep[k]:
                    print(' got', gp[k]); print(' exp', ep[k]); break
            if len(got['probes']) != len(exp['probes']):
                print(' counts', len(got['probes']), len(exp['probes']))
            if fails > 2: break
    print('plan fuzz done, %d mismatches out of %d' % (fails, trials))
    return 1 if fails else 0

sys.exit(main())
